text:
& label {
  flex: 1;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  line-height: 1.5;

  & span {
    flex: 1;
    inline-size: 0;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  @media (-moz-overlay-scrollbars) {
    padding-inline-end: env(scrollbar-inline-size);
  }
}

&
  tr:is(
    [data-properties~="server-type-imap"],
    [data-properties~="server-type-pop3"],
    [data-properties~="server-type-ews"],
    [data-properties~="server-type-graph"],
    [data-properties~="server-type-nntp"],
    [data-properties~="server-type-rss"],
    [data-properties~="server-type-none"]
  ) {
  font-weight: bold;

  & img.icon {
    color: var(--primary);
  }
}

& tr[data-properties~="noselect"] {
  opacity: 0.6;
  font-style: italic;
}

